import * as React from 'react';
import { expect, it, vi } from 'vitest';
import { render, fireEvent, screen, act, cleanup } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';
import { afterEach } from 'vitest';
afterEach(cleanup);

it('null controlled: state stale', () => {
  function App() {
    const [value, setValue] = React.useState<string | null>('a');
    return (
      <Field.Root data-testid="root">
        <Field.Control value={value as any} onValueChange={(v) => setValue(v || null)} />
      </Field.Root>
    );
  }
  render(<App />);
  const c = screen.getByRole('textbox');
  fireEvent.change(c, { target: { value: 'ab' } });
  console.log('after ab', screen.getByTestId('root').getAttribute('data-dirty'), screen.getByTestId('root').getAttribute('data-filled'));
  fireEvent.change(c, { target: { value: '' } });
  console.log('after empty->null filled=', screen.getByTestId('root').getAttribute('data-filled'), 'dirty=', screen.getByTestId('root').getAttribute('data-dirty'));
});

it('controlled prevented change clears server error', () => {
  function App() {
    const [value, setValue] = React.useState('');
    return (
      <Form errors={{ message: 'Server error' }}>
        <Field.Root name="message" validationMode="onChange">
          <Field.Control value={value} onValueChange={setValue} />
          <Field.Error />
        </Field.Root>
      </Form>
    );
  }
  render(<App />);
  const control = screen.getByRole('textbox');
  control.addEventListener('input', (e) => e.preventDefault(), { capture: true, once: true });
  fireEvent.input(control, { cancelable: true, target: { value: 'a' } });
  console.log('server error present:', !!screen.queryByText('Server error'));
});

it('cancel still marks dirty', () => {
  render(
    <Field.Root data-testid="root">
      <Field.Control onValueChange={(v, d) => d.cancel()} />
    </Field.Root>,
  );
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
  console.log('canceled dirty=', screen.getByTestId('root').getAttribute('data-dirty'), 'filled=', screen.getByTestId('root').getAttribute('data-filled'));
});

it('reset to empty in onChange mode shows required error', () => {
  function App() {
    const [value, setValue] = React.useState('');
    return (
      <Field.Root validationMode="onChange" data-testid="root">
        <Field.Control required value={value} onValueChange={setValue} />
        <button onClick={() => setValue('')}>reset</button>
      </Field.Root>
    );
  }
  render(<App />);
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'x' } });
  fireEvent.click(screen.getByRole('button'));
  console.log('after reset invalid=', screen.getByTestId('root').getAttribute('data-invalid'), 'dirty=', screen.getByTestId('root').getAttribute('data-dirty'));
});

it('submit validate receives type', async () => {
  const validate = vi.fn(() => null);
  function App() {
    const [value, setValue] = React.useState(5);
    return (
      <Form>
        <Field.Root name="n" validate={validate}>
          <Field.Control value={value} onValueChange={(v) => setValue(Number(v))} />
        </Field.Root>
        <button type="submit">s</button>
      </Form>
    );
  }
  render(<App />);
  await act(async () => { fireEvent.click(screen.getByRole('button')); });
  console.log('validate arg type', typeof (validate.mock.calls.at(-1) as any)?.[0], JSON.stringify(validate.mock.calls));
});
EOF
